#!/usr/bin/env bash
# PreToolUse hook for Edit|Write|MultiEdit.
#
# temper.out/ is regenerated by every build. An edit there is lost on the
# next build and never reaches a backend user. Fix the Temper source instead.
set -uo pipefail
input=$(cat)
path=$(printf '%s' "$input" | jq -r '.tool_input.file_path // .tool_input.path // empty' 2>/dev/null)
case "$path" in
  */temper.out/*)
    echo "Blocked: $path is generated by 'temper build'. Edit the .temper source under src/ and rebuild." >&2
    exit 2 ;;
esac
exit 0
